<?php require_once __DIR__.'/../_bootstrap.php';$u=user();$id=trim($_GET['identifier']??'');if(!$id)fail('Identifier is required.');$s=db()->prepare('SELECT s.*,p.name,p.unique_identifier FROM sales s JOIN products p ON p.id=s.product_id WHERE p.unique_identifier=? AND s.seller_id=? AND s.id NOT IN(SELECT sale_id FROM returns) ORDER BY s.sold_at DESC LIMIT 1');$s->execute([$id,$u['id']]);$sale=$s->fetch();if(!$sale)fail('Eligible sale not found.',404);$sale['warranty_status']=!$sale['warranty_months']?'no_warranty':(strtotime($sale['warranty_ends_at'])>=strtotime(date('Y-m-d'))?'valid':'expired');out(['success'=>true,'sale'=>$sale]);
